function getDivisors($n) {
    $divisors = [];
    for ($i = 1; $i * $i <= $n; $i++) {
        if ($n % $i == 0) {
            $divisors[] = $i;
            if ($i != $n / $i) {
                $divisors[] = $n / $i;
            }
        }
    }
    return $divisors;
}

